import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    // 3 mục: 'xem' (Xem thông báo), 'admin' (Gửi Admin), 'nhom' (Gửi nhóm chung)
    const [activeTab, setActiveTab] = useState('xem');

    return (
        <div style={styles.container}>
            <header style={styles.header}>
                <h2 style={{color: '#2e7d32'}}>🔔 Trung tâm thông báo & Kết nối</h2>
                <p style={{color: '#666'}}>Xem tin tức từ tòa nhà và tương tác với cộng đồng</p>
            </header>

            {/* Thanh điều hướng 3 mục */}
            <div style={styles.tabContainer}>
                <button 
                    onClick={() => setActiveTab('xem')} 
                    style={{...styles.tab, borderBottom: activeTab === 'xem' ? '3px solid #2e7d32' : 'none', color: activeTab === 'xem' ? '#2e7d32' : '#888'}}
                >
                    📢 Xem thông báo
                </button>
                <button 
                    onClick={() => setActiveTab('admin')} 
                    style={{...styles.tab, borderBottom: activeTab === 'admin' ? '3px solid #1976d2' : 'none', color: activeTab === 'admin' ? '#1976d2' : '#888'}}
                >
                    👨‍💼 Gửi Admin
                </button>
                <button 
                    onClick={() => setActiveTab('nhom')} 
                    style={{...styles.tab, borderBottom: activeTab === 'nhom' ? '3px solid #ed6c02' : 'none', color: activeTab === 'nhom' ? '#ed6c02' : '#888'}}
                >
                    👥 Nhóm chung
                </button>
            </div>

            {/* Nội dung tương ứng từng mục */}
            <div style={styles.content}>
                {activeTab === 'xem' && (
                    <div style={styles.list}>
                        <div style={styles.newsCard}>
                            <span style={styles.badge}>MỚI</span>
                            <h4>Thông báo bảo trì thang máy tòa A</h4>
                            <p style={styles.date}>17/04/2026 | Ban Quản Lý</p>
                            <p>Thang máy số 3 tòa A sẽ tạm dừng hoạt động để bảo trì định kỳ từ 14h-16h...</p>
                            <button style={styles.linkBtn}>Chi tiết</button>
                        </div>
                    </div>
                )}

                {activeTab === 'admin' && (
                    <div style={styles.formCard}>
                        <h3 style={{color: '#1976d2', marginBottom: '15px'}}>Gửi yêu cầu/Phản hồi tới Admin</h3>
                        <input type="text" placeholder="Chủ đề (Vd: Báo hỏng thiết bị, Khiếu nại...)" style={styles.input} />
                        <textarea placeholder="Nội dung chi tiết cư dân cần hỗ trợ..." style={styles.textarea}></textarea>
                        <button style={{...styles.submitBtn, backgroundColor: '#1976d2'}}>Gửi tới Ban quản lý</button>
                    </div>
                )}

                {activeTab === 'nhom' && (
                    <div style={styles.formCard}>
                        <h3 style={{color: '#ed6c02', marginBottom: '15px'}}>Đăng tin lên Nhóm chung cư dân</h3>
                        <textarea 
                            placeholder="Chia sẻ thông tin với hàng xóm (Vd: Tìm đồ lạc, rủ mua chung, nhắc nhở chung...)" 
                            style={{...styles.textarea, borderColor: '#ed6c02'}}
                        ></textarea>
                        <button style={{...styles.submitBtn, backgroundColor: '#ed6c02'}}>Đăng lên bảng tin chung</button>
                    </div>
                )}
            </div>
        </div>
    );
};

const styles = {
    container: { padding: '20px', width: '100%' },
    header: { marginBottom: '25px' },
    tabContainer: { display: 'flex', gap: '20px', borderBottom: '1px solid #ddd', marginBottom: '25px' },
    tab: { padding: '10px 15px', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '15px' },
    content: { minHeight: '300px' },
    newsCard: { backgroundColor: '#fff', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)', borderLeft: '5px solid #2e7d32' },
    badge: { backgroundColor: '#ff4d4f', color: '#fff', padding: '2px 8px', borderRadius: '4px', fontSize: '11px' },
    date: { fontSize: '12px', color: '#999', margin: '5px 0' },
    linkBtn: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px' },
    formCard: { backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 12px rgba(0,0,0,0.05)' },
    input: { width: '100%', padding: '12px', marginBottom: '15px', borderRadius: '8px', border: '1px solid #ddd', boxSizing: 'border-box' },
    textarea: { width: '100%', padding: '12px', height: '120px', marginBottom: '15px', borderRadius: '8px', border: '1px solid #ddd', boxSizing: 'border-box', resize: 'none' },
    submitBtn: { padding: '12px 25px', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', width: '100%' }
};

export default QuanLyThongBaoCuDan;
